CREATE TEMPORARY VIEW user_exp_mapping_7d_${grass_region_without_quote} AS
SELECT
    user_id
    ,local_date
    ,exp_group_id
    ,experiment_id  
FROM
    srdi_mart.dim_sr_data_warehouse_abtest_user_group
WHERE
    grass_region = ${grass_region}
    AND local_date BETWEEN DATE_SUB(${local_date}, 7) AND ${local_date}
    AND is_assignment_log = 1
    AND is_search_whitelist = 1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_item_${grass_region_without_quote}  AS
SELECT
    item_id
    ,local_date
    ,level1_global_be_category_id
    ,level2_global_be_category_id
    ,level1_global_be_category
    ,level2_global_be_category
FROM
    srdi_mart.dim_sr_data_warehouse_item
WHERE
    grass_region = ${grass_region}
    AND local_date BETWEEN DATE_SUB(${local_date}, 7) AND ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_order_nmv_platform_${grass_region_without_quote} AS
SELECT
    user_id
    ,a.local_date
    ,CASE
        WHEN platform in( 'android_app' ,'ios_app','android_app_lite','pc_web','android_web','ios_web') THEN platform
        ELSE 'other'
    END AS platform
    ,COALESCE(cast(level1_global_be_category_id AS STRING), 'NA') AS level1_global_be_category_id
    ,COALESCE(cast(level2_global_be_category_id AS STRING), 'NA') AS level2_global_be_category_id
    ,COALESCE(cast(level1_global_be_category AS STRING), 'NA') AS level1_global_be_category
    ,COALESCE(cast(level2_global_be_category AS STRING), 'NA') AS level2_global_be_category
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv) AS nmv_usd
FROM
    srdi_mart.dwd_sr_data_warehouse_platform_nmv a
    LEFT JOIN dim_item_${grass_region_without_quote} b 
        ON a.item_id = b.item_id
        AND a.local_date = b.local_date
WHERE
    grass_region = ${grass_region}
    AND a.local_date BETWEEN DATE_SUB(${local_date}, 7) AND ${local_date}
    AND user_id > 0
    AND (
            (reporting_business_line = 'Search' AND reporting_module IN ('Global Search'))
            OR (source1_reporting_business_line = 'Search' AND source1_reporting_module IN ('Global Search'))
            OR (source2_reporting_business_line = 'Search' AND source2_reporting_module IN ('Global Search'))
        )
GROUP BY
    1,2,3,4,5,6,7;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_order_nmv_platform_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,experiment_id
    ,a.local_date AS local_date
    ,COALESCE(platform, '__ALL__') AS platform
    ,COALESCE(level1_global_be_category_id, '__ALL__') AS level1_global_be_category_id
    ,COALESCE(level2_global_be_category_id, '__ALL__') AS level2_global_be_category_id
    ,COALESCE(level1_global_be_category, '__ALL__') AS level1_global_be_category
    ,COALESCE(level2_global_be_category, '__ALL__') AS level2_global_be_category
    ,SUM(net_order_cnt) AS net_order_cnt
    ,SUM(nmv_usd) AS nmv_usd
FROM
    dwm_order_nmv_platform_${grass_region_without_quote} a
JOIN
    user_exp_mapping_7d_${grass_region_without_quote} b
ON
    a.user_id = b.user_id
    AND a.local_date = b.local_date
GROUP BY GROUPING SETS
(
    (a.local_date, exp_group_id, experiment_id, platform, level1_global_be_category_id, level2_global_be_category_id, level1_global_be_category, level2_global_be_category)
    ,(a.local_date, exp_group_id, experiment_id, level1_global_be_category_id, level2_global_be_category_id, level1_global_be_category, level2_global_be_category)
    ,(a.local_date, exp_group_id, experiment_id, platform, level2_global_be_category_id, level2_global_be_category)
    ,(a.local_date, exp_group_id, experiment_id, level2_global_be_category_id, level2_global_be_category)
    ,(a.local_date, exp_group_id, experiment_id, platform, level1_global_be_category_id, level1_global_be_category)
    ,(a.local_date, exp_group_id, experiment_id, level1_global_be_category_id, level1_global_be_category)
    ,(a.local_date, exp_group_id, experiment_id, platform)
    ,(a.local_date, exp_group_id, experiment_id)
);

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_item_category_platform_nmv_metrics_1d
PARTITION (
    grass_region=${grass_region},
    local_date
)
SELECT 
    a.exp_group_id
    ,a.experiment_id
    ,a.platform
    ,a.level1_global_be_category_id
    ,a.level2_global_be_category_id
    ,a.level1_global_be_category
    ,a.level2_global_be_category

    ,net_order_cnt
    ,nmv_usd AS nmv
    ,local_date
FROM 
    dws_order_nmv_platform_${grass_region_without_quote} a;
